import sys
def main():
    data = sys.stdin.read().split()
    n = int(data[0]); d = int(data[1])
    tags = sorted((int(data[2 + 2 * i]), int(data[3 + 2 * i])) for i in range(n))
    ans = 0
    for i in range(n):
        xi, si = tags[i]
        for j in range(i + 1, n):
            xj, sj = tags[j]
            if xj - xi > d:
                break
            if sj != si:
                ans += 1
    print(ans)
main()
